import json
import os
import re
import smtplib
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
from urllib.request import Request, urlopen
from dotenv import load_dotenv

# Application to read fedora releases.json, parse for the latest stable release,
# and send an email notification if a new release is identified.
#
# About 80% of this code was generated by Google search AI.  I added the relocation of
# secure properties to .env and revised the logic slightly for updating the version cache
# file so it would remain unchanged if the email send action failed.

# --- CONFIGURATION ---
URL = "https://fedoraproject.org/releases.json"

# use an absolute path so that it will work reliably with scheduling
# revise path accordingly
CACHE_FILE = os.path.expanduser("/Users/kelly/.fedora_latest_version")

# dotenv used as PyCharm wasn't working reliably with .env files in the
# python environment itself.  Revise the folder path for your environment
load_dotenv(dotenv_path="/Users/kelly/PycharmProjects/FedoraLatestRelease/.env")

# Email Settings (Using an App Password is required for modern SMTP providers)
SMTP_SERVER = "smtp.gmail.com"  # e.g., smtp.gmail.com, ://yahoo.com, etc.
SMTP_PORT = 587  # 587 for TLS
SENDER_EMAIL = os.getenv("GOOGLE_SENDER_EMAIL")
SENDER_PASSWORD = os.getenv("GOOGLE_SENDER_PASSWORD")
SENDER_PASSWORD = (
    SENDER_PASSWORD
)
RECEIVER_EMAIL = os.getenv("RECEIVER_EMAIL")


def get_latest_stable_fedora():
    """Fetches the highest stable numeric release version from Fedora."""
    try:
        req = Request(
            URL, headers={"User-Agent": "FedoraVersionNotifier/1.0 (macOS)"}
        )
        with urlopen(req) as response:
            if response.status != 200:
                return None
            data = json.loads(response.read().decode("utf-8"))

        stable_versions = []
        for release in data:
            version_str = str(release.get("version", ""))
            if re.match(r"^\d+$", version_str):
                stable_versions.append(int(version_str))

        return max(stable_versions) if stable_versions else None
    except Exception:
        return None


def get_cached_version():
    """Reads the last known version from the local cache file."""
    if os.path.exists(CACHE_FILE):
        try:
            with open(CACHE_FILE, "r") as f:
                return int(f.read().strip())
        except ValueError:
            return None
    return None


def update_cached_version(version):
    """Saves the newest version to the local cache file."""
    with open(CACHE_FILE, "w") as f:
        f.write(str(version))


def send_email(new_version):
    """Constructs and sends the email alert."""
    msg = MIMEMultipart()
    msg["From"] = SENDER_EMAIL
    msg["To"] = RECEIVER_EMAIL
    msg["Subject"] = f"🚨 New Fedora Stable Release Detected: Fedora {new_version}!"

    body = f"""Hello,

A new version of Fedora Linux has officially dropped! 

Latest Stable Version: Fedora {new_version}

You can find more information or grab the download images directly on the official page:
https://fedoraproject.org/

To upgrade from the previous version:
# sudo dnf upgrade --refresh (reboot if kernel upgrades)
# sudo dnf install dnf-plugin-system-upgrade
# sudo dnf system-upgrade download --refresh --releasever={new_version}
# sudo dnf system-upgrade reboot

Best regards,
Your macOS Automation Script
"""
    msg.attach(MIMEText(body, "plain"))

    try:
        # Connect to server and secure via TLS
        server = smtplib.SMTP(SMTP_SERVER, SMTP_PORT)
        server.starttls()
        # print(f"SENDER_EMAIL= {SENDER_EMAIL}; SENDER_PASSWORD={SENDER_PASSWORD}")
        server.login(SENDER_EMAIL, SENDER_PASSWORD)
        server.send_message(msg)
        server.quit()
        print(f"Success: Notification email sent for Fedora {new_version}.")
        return True # Success
    except Exception as e:
        print(f"Error sending email: {e}")
        return False #failure


def main():
    current_latest = get_latest_stable_fedora()
    if not current_latest:
        print("Failed to fetch or parse Fedora version data.")
        return

    cached_version = get_cached_version()

    # Case 1: First time running, populate the cache silently without triggering a backlogged alert
    if cached_version is None:
        print(
            f"Initial setup: Tracking started. Current Fedora version is {current_latest}."
        )
        update_cached_version(current_latest)

    # Case 2: A newer version is found!
    elif current_latest > cached_version:

        if send_email(current_latest):
            print(
                f"New release found and mail successfully sent! "
                f"Upgrading tracked version from {cached_version} to {current_latest}."
            )
            update_cached_version(current_latest)
        else:
            print("Tracked version not updated due to email send failure.")

    # Case 3: No changes
    else:
        print(
            f"No updates. Checked version ({current_latest}) matches tracked version ({cached_version})."
        )


if __name__ == "__main__":
    main()
